import unittest

from assets import asset_key


class AssetKeyTests(unittest.TestCase):
    def test_normalizes_name_and_builds_storage_key(self):
        self.assertEqual(
            asset_key("  Hello---World\tAgain  ", 3),
            "assets/v3/hello_world_again.bin",
        )

    def test_preserves_characters_outside_whitespace_and_hyphens(self):
        self.assertEqual(asset_key("a/b?c", 1), "assets/v1/a/b?c.bin")

    def test_rejects_empty_or_non_string_names(self):
        for name in ("", "   ", "---"):
            with self.subTest(name=name):
                with self.assertRaises(ValueError):
                    asset_key(name, 1)

        for name in (None, 123):
            with self.subTest(name=name):
                with self.assertRaises(TypeError):
                    asset_key(name, 1)

    def test_requires_positive_integer_revision(self):
        for revision in (0, -1, 1.0, "1", True, None):
            with self.subTest(revision=revision):
                with self.assertRaises(ValueError):
                    asset_key("valid", revision)


if __name__ == "__main__":
    unittest.main()

